/**
 * Which planet's surroundings a material wears. The planet that holds the
 * visitor puts its air's veil, its clouds' shadows, its water and the rest on
 * the scene's materials as plugins; a planet that does not hold them is
 * outside that air, so its ground is "away" and takes none of them. When
 * another planet comes to hold the visitor, the first one's plugins, turned
 * off, are still on the materials: the new planet takes them up again for
 * itself rather than adding a second of each.
 */

/** A material plugin a planet's surroundings put on, which can be handed to another planet's state. */
export interface HandedPlugin<S> {
  isEnabled: boolean;
  /** Draws from `state` from now on: the planet that holds the visitor now. */
  rebind(state: S): void;
}

const away = new WeakSet<object>();

/** Marks a material as a planet's that does not hold the visitor (on), or as one again that does (off). */
export function setAway(material: object, on: boolean): void {
  if (on) away.add(material);
  else away.delete(material);
}

export const isAway = (material: object): boolean => away.has(material);

/**
 * The plugin named `name` for `state` on `material`: a new one, or one a
 * planet that let the visitor go left there, turned on again; undefined when
 * the material is away, or already wears a live one.
 */
export function takePlugin<S, P extends HandedPlugin<S>>(
  material: { pluginManager?: { getPlugin(name: string): unknown } | null },
  name: string,
  state: S,
  make: () => P,
): P | undefined {
  if (away.has(material)) return undefined;
  const have = material.pluginManager?.getPlugin(name) as P | null | undefined;
  if (!have) return make();
  if (have.isEnabled) return undefined;
  have.rebind(state);
  have.isEnabled = true;
  return have;
}
